(()=>{'use strict';
const root=document.querySelector('.v2');if(!root)return;
const KEY='nemesis-cart-v1',money=n=>Number(n||0).toLocaleString('pt-BR',{minimumFractionDigits:2}),price=e=>Number(String(e||'').replace(/[^0-9,.-]/g,'').replace(/\./g,'').replace(',','.'))||0;
const state=new Map(Object.entries(JSON.parse(localStorage.getItem(KEY)||'{}')).map(([k,v])=>[k,v]));
const save=()=>localStorage.setItem(KEY,JSON.stringify(Object.fromEntries(state)));
const rows=()=>[...state.values()].filter(x=>x.qty>0),lineTotal=x=>x.kind==='application'&&x.qty>=2?x.qty*25:x.qty*x.price,total=()=>rows().reduce((s,x)=>s+lineTotal(x),0);
const add=(name,p,qty=1)=>{let x=state.get(name)||{name,price:p||0,qty:0};x.price=p||x.price;x.qty+=Math.max(1,qty);state.set(name,x);save();render()};
const setQty=(name,q)=>{let x=state.get(name);if(!x)return;q<=0?state.delete(name):x.qty=q;save();render()};
const button=document.createElement('button');button.type='button';button.id='nemesis-cart-toggle';button.className='nemesis-cart-toggle';button.setAttribute('aria-label','Abrir carrinho');
const panel=document.createElement('aside');panel.id='nemesis-cart-panel';panel.className='nemesis-cart-panel';panel.innerHTML='<div class="nemesis-cart-head"><b>Seu carrinho</b><button type="button" data-close>×</button></div><div class="nemesis-cart-lines"></div><div class="nemesis-cart-total"></div><button type="button" class="btn nemesis-checkout">Finalizar pedido no WhatsApp</button>';
document.querySelectorAll('.cart-float,.nfc-cart,.cart-panel').forEach(x=>x.remove());
const css=document.createElement('style');css.textContent='.cart-float,.nfc-cart,.cart-panel{display:none!important}.nemesis-cart-toggle{position:fixed!important;right:16px!important;bottom:16px!important;z-index:9999!important;width:46px!important;height:46px!important;padding:0!important;border:1px solid #ffffff55!important;border-radius:50%!important;background:#ffffff18!important;color:#fff!important;backdrop-filter:blur(14px)!important;box-shadow:0 8px 26px #000b!important;cursor:pointer!important;transition:none!important}.nemesis-cart-toggle:before{content:"🛒";font-size:18px}.nemesis-cart-toggle:after{content:attr(data-count);position:absolute;right:-4px;top:-5px;min-width:17px;height:17px;border-radius:99px;background:#ff5262;color:#fff;font:700 10px/17px Arial}.nemesis-cart-panel{position:fixed!important;right:16px!important;bottom:72px!important;z-index:9998!important;width:min(340px,calc(100vw - 32px));padding:16px;border:1px solid #ffffff2c;border-radius:18px;background:#08090cf2;color:#fff;box-shadow:0 18px 45px #000b;backdrop-filter:blur(18px);opacity:0;transform:none;pointer-events:none;transition:opacity .18s ease}.nemesis-cart-panel.is-open{opacity:1;pointer-events:auto}.nemesis-cart-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px}.nemesis-cart-head button{border:0;background:transparent;color:#fff;font-size:24px;cursor:pointer}.nemesis-cart-lines{display:grid;gap:8px;max-height:220px;overflow:auto}.nemesis-cart-row{display:grid;grid-template-columns:1fr auto;gap:8px;padding:9px 0;border-bottom:1px solid #ffffff18;font-size:13px}.nemesis-cart-row small{display:block;color:#bfc4d4;margin-top:3px}.nemesis-cart-qty{display:flex;gap:5px;align-items:center}.nemesis-cart-qty button{width:24px;height:24px;border:1px solid #ffffff40;border-radius:7px;background:#ffffff14;color:#fff;cursor:pointer}.nemesis-cart-total{margin:14px 0;font-size:16px;font-weight:800}.nemesis-checkout{width:100%!important}.nemesis-add-control{display:block;width:100%;margin-top:10px}.choice .nemesis-add-control{grid-column:1/-1}.nfc-quantity-controls{display:flex;align-items:center;gap:8px}.nfc-quantity-controls button{width:34px;height:34px;border:1px solid #ffffff40;border-radius:9px;background:#ffffff14;color:#fff;font-size:20px;cursor:pointer}.nfc-quantity-controls input{margin:0!important;text-align:center}';document.head.append(css);document.body.append(button,panel);
const open=()=>panel.classList.add('is-open'),close=()=>panel.classList.remove('is-open');button.onclick=()=>panel.classList.contains('is-open')?close():open();panel.querySelector('[data-close]').onclick=close;
const render=()=>{button.dataset.count=String(rows().reduce((s,x)=>s+x.qty,0));panel.querySelector('.nemesis-cart-lines').innerHTML=rows().length?rows().map(x=>'<div class="nemesis-cart-row"><div>'+x.name+'<small>R$ '+money(lineTotal(x))+' · '+x.qty+' unidade(s)</small></div><div class="nemesis-cart-qty"><button type="button" data-minus="'+encodeURIComponent(x.name)+'">−</button><b>'+x.qty+'</b><button type="button" data-plus="'+encodeURIComponent(x.name)+'">+</button></div></div>').join(''):'<p>Seu carrinho está vazio.</p>';panel.querySelector('.nemesis-cart-total').textContent='Total: R$ '+money(total());const summary=root.querySelector('#v2-selected');if(summary)summary.textContent=rows().length?'Carrinho: '+rows().map(x=>x.name+' × '+x.qty).join(' • ')+' | Total: R$ '+money(total()):'Nenhum item selecionado.'};
root.querySelectorAll('.choice input[data-item]').forEach(input=>{const card=input.closest('.choice');if(!card||card.querySelector('.nemesis-add-control'))return;const name=input.dataset.item||card.querySelector('b')?.textContent?.trim()||'Item',p=price(card.querySelector('.price,.v2-price,strong')?.textContent||card.textContent),b=document.createElement('button');b.type='button';b.className='btn nemesis-add-control';b.textContent='Adicionar ao carrinho';b.onclick=()=>{add(name,p);input.checked=true;b.textContent='Adicionado · '+state.get(name).qty;open()};card.append(b)});
const q=root.querySelector('#nfc-quantity'),order=q?.closest('.nfc-order'),nfcButton=order?.querySelector('.nfc-add');if(q&&order){const wrap=document.createElement('div');wrap.className='nfc-quantity-controls';const minus=document.createElement('button'),plus=document.createElement('button');minus.type=plus.type='button';minus.textContent='−';plus.textContent='+';q.parentNode.insertBefore(wrap,q);wrap.append(minus,q,plus);minus.onclick=()=>{q.value=Math.max(1,(Number(q.value)||1)-1);q.dispatchEvent(new Event('input',{bubbles:true}))};plus.onclick=()=>{q.value=(Number(q.value)||1)+1;q.dispatchEvent(new Event('input',{bubbles:true}))};const b=nfcButton||document.createElement('button');b.type='button';b.className='btn nemesis-add-control';b.textContent='Adicionar ao carrinho';b.onclick=()=>{add('Plaquinha NFC + QR Code',60,Math.max(1,Number(q.value)||1));const c=root.querySelector('#nfc-selected');if(c)c.checked=true;b.textContent='Adicionado ao carrinho · '+(state.get('Plaquinha NFC + QR Code')?.qty||1);open()};if(!nfcButton)order.append(b)}
panel.addEventListener('click',e=>{const z=e.target.closest('[data-plus],[data-minus]');if(z){const n=decodeURIComponent(z.dataset.plus||z.dataset.minus),x=state.get(n);setQty(n,(x?.qty||0)+(z.dataset.plus?1:-1))}});
const catalog={'Cadastro no Google':250,'Atualização do Google':150,'Biosite personalizado':150};
root.querySelectorAll('.nfc-product .add-nfc').forEach(b=>{const card=b.closest('.nfc-product'),input=card.querySelector('.qty');if(input){const control=document.createElement('div');control.className='nfc-quantity-controls';const less=document.createElement('button'),more=document.createElement('button');less.type=more.type='button';less.textContent='−';more.textContent='+';input.before(control);control.append(less,input,more);less.onclick=()=>input.value=Math.max(1,(Number(input.value)||1)-1);more.onclick=()=>input.value=(Number(input.value)||1)+1}b.onclick=()=>{const name=input?.dataset.nfcName,qty=Math.max(1,Number(input?.value)||1);if(!name)return;add(name,30,qty);state.get(name).kind='application';save();render();b.textContent='Adicionado · '+state.get(name).qty;open()}});
root.querySelectorAll('.block .sales-cta').forEach(b=>{const section=b.closest('.block'),title=section?.querySelector('h2')?.textContent||'',name=Object.keys(catalog).find(k=>title.includes(k));if(!name)return;b.onclick=()=>{add(name,catalog[name]);b.textContent='Adicionado · '+state.get(name).qty;open()}});
root.querySelectorAll('.bio-card .v2-buy').forEach(b=>b.onclick=()=>{add('Biosite personalizado',150);open()});
const checkout=()=>{const a=rows();if(!a.length)return open();const ph=String(window.NEMESIS_CHECKOUT_PHONE||'').replace(/\D/g,''),msg='Olá! Quero finalizar meu pedido:\n'+a.map(x=>'- '+x.name+' × '+x.qty+' = R$ '+money(lineTotal(x))).join('\n')+'\nTotal: R$ '+money(total());if(ph)window.open('https://wa.me/'+ph+'?text='+encodeURIComponent(msg),'_blank');else alert('O WhatsApp comercial ainda não foi configurado.')};
panel.querySelector('.nemesis-checkout').onclick=checkout;
const bottomCheckout=root.querySelector('#v2-whatsapp');if(bottomCheckout)bottomCheckout.onclick=checkout;
document.querySelectorAll('.admin-open,.admin-panel').forEach(x=>x.remove());
render();
})();
